const input = $json ?? {};
const deal = input.deal ?? input.transaction ?? input;
const authorization = input.closing_authorization ?? input.authorization ?? {};
const readiness = input.final_closing_readiness ?? input.transaction_readiness ?? {};
const execution = input.closing_execution ?? {};

const identityComplete = Boolean(deal.deal_id ?? deal.transaction_id) &&
  Boolean(deal.property_id) &&
  Boolean(deal.lead_id ?? deal.seller_id);
const executedAgreement = String(deal.execution_state ?? deal.agreement?.execution_state ?? '').toLowerCase() === 'executed';
const signedEvidence = Boolean(deal.signed_evidence ?? deal.agreement?.signed_evidence);
const agreementType = String(deal.agreement_type ?? deal.agreement?.type ?? '').toLowerCase();
const validAgreementType = ['assignment','novation','double_close'].includes(agreementType);

const agreedPrice = Number(deal.agreed_price ?? deal.purchase_price ?? deal.contract_price);
const effectiveMao = Number(deal.effective_mao ?? deal.mao ?? deal.underwriting?.effective_mao);
const priceWithinMao = Number.isFinite(agreedPrice) && Number.isFinite(effectiveMao) && agreedPrice <= effectiveMao;

const authApproved = Boolean(authorization.approved ?? authorization.authorized ?? authorization.confirmed);
const authType = String(authorization.type ?? '').toLowerCase();
const validAuth = authApproved && ['human_approval','closing_authorization','authorized'].includes(authType || 'authorized');

const readinessStatus = String(input.decision?.status ?? input.final_closing_status ?? '').toLowerCase();
const readinessReady = readinessStatus === 'final_closing_ready' || Boolean(readiness.ready);
const executionState = String(execution.status ?? '').toLowerCase();
const alreadyLaunched = ['launched','initiated','in_progress'].includes(executionState);

const closingDate = execution.closing_date ?? readiness.closing_date ?? deal.closing_date ?? deal.critical_dates?.closing_date ?? null;
const closingDateValid = Boolean(closingDate && !Number.isNaN(new Date(closingDate).getTime()));
const blockers = [
  ...(Array.isArray(deal.blockers) ? deal.blockers : []),
  ...(Array.isArray(readiness.blockers) ? readiness.blockers : []),
  ...(Array.isArray(execution.blockers) ? execution.blockers : [])
].filter(Boolean);

let status = 'launch_blocked';
let severity = 'urgent';

if (!identityComplete || !executedAgreement || !signedEvidence || !validAgreementType || !priceWithinMao) {
  status = 'launch_blocked';
  severity = 'urgent';
} else if (!readinessReady || !validAuth || !closingDateValid || blockers.length) {
  status = 'authorization_or_readiness_required';
  severity = 'high';
} else if (alreadyLaunched) {
  status = 'already_launched';
  severity = 'normal';
} else {
  status = 'launch_ready';
  severity = 'normal';
}

const routing = status === 'launch_ready' || status === 'already_launched'
  ? {next_workflow:'WF-126',reason:'Final authorization is satisfied; continue closing execution coordination.'}
  : {next_workflow:'WF-126',reason:'Closing execution cannot safely launch until authorization/readiness blockers are resolved.'};

return [{
  json:{
    ...input,
    workflow_id:'WF-178',
    workflow_name:'Final Closing Authorization → Closing Execution Launch Controller',
    decision:{status,severity},
    identity_complete:identityComplete,
    executed_agreement:executedAgreement,
    signed_evidence_present:signedEvidence,
    agreement_type:agreementType || null,
    valid_agreement_type:validAgreementType,
    agreed_price:Number.isFinite(agreedPrice) ? agreedPrice : null,
    effective_mao:Number.isFinite(effectiveMao) ? effectiveMao : null,
    price_within_mao:priceWithinMao,
    readiness_ready:readinessReady,
    authorization_approved:authApproved,
    authorization_type:authType || null,
    valid_authorization:validAuth,
    closing_date:closingDate,
    closing_date_valid:closingDateValid,
    execution_state:executionState || null,
    already_launched:alreadyLaunched,
    blockers,
    launch_status:status,
    routing
  }
}];

const out = $json ?? {};
return [{
  json:{
    ...out,
    workflow_id:'WF-178',
    result:'closing_execution_launch_evaluated',
    next_workflow:out.routing?.next_workflow ?? 'WF-126'
  }
}];
